const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');
db.exec(`CREATE TABLE IF NOT EXISTS metrics_call_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    article_id TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('processing','success','failed','uncertain','skipped')),
    provider TEXT NOT NULL DEFAULT 'jizhile',
    run_id TEXT,
    feishu_record_id TEXT,
    url TEXT NOT NULL,
    request_hash TEXT,
    result_json TEXT,
    read_count INTEGER,
    like_count INTEGER,
    wow_count INTEGER,
    share_count INTEGER,
    collect_count INTEGER,
    comment_count INTEGER,
    error_code TEXT,
    error_msg TEXT,
    started_at INTEGER NOT NULL,
    finished_at INTEGER,
    lock_until INTEGER NOT NULL,
    synced_to_feishu INTEGER NOT NULL DEFAULT 0
  );
  CREATE UNIQUE INDEX IF NOT EXISTS ux_metrics_processing_once ON metrics_call_log(article_id) WHERE status = 'processing';
  CREATE INDEX IF NOT EXISTS idx_metrics_article_status_time ON metrics_call_log(article_id, status, started_at);
  CREATE INDEX IF NOT EXISTS idx_metrics_sync ON metrics_call_log(status, synced_to_feishu);`);
db.close();
const sd = $getWorkflowStaticData('global');
sd.stage3_run_stats = {
  total_records: 0, cache_hit_count: 0, claimed_count: 0,
  skipped_processing_count: 0, success_count: 0, failed_count: 0,
  uncertain_count: 0, run_started_at: Date.now()
};
return items;

function getField(fields, name) {
  const val = fields?.[name];
  if (val === null || val === undefined) return '';
  if (typeof val === 'string') return val;
  if (typeof val === 'number') return String(val);
  if (Array.isArray(val)) {
    if (!val.length) return '';
    const first = val[0];
    if (typeof first === 'object' && first !== null) {
      return first.link || first.text || first.name || first.url || JSON.stringify(first);
    }
    return val.map(seg => {
      if (typeof seg === 'string') return seg;
      if (seg?.text) return String(seg.text);
      return '';
    }).join('');
  }
  if (typeof val === 'object') {
    return val.link || val.text || val.name || val.url || JSON.stringify(val);
  }
  return String(val);
}

function getTimestamp(fields, name) {
  const val = fields?.[name];
  if (val === null || val === undefined) return null;
  if (typeof val === 'number') return val;
  if (typeof val === 'string' && /^\d+$/.test(val.trim())) return Number(val.trim());
  return null;
}

const now = Date.now();
const cutoff = now - 86400 * 1000;

const resp = items[0]?.json || {};
const records = resp.data?.items || resp.items || resp.records || resp.data?.records || [];
if (!records.length) return [];

return records
  .map(r => ({
    json: {
      record_id: r.record_id || r.id || '',
      article_id: getField(r.fields, 'article_id'),
      url: getField(r.fields, '地址'),
      publish_time_ms: getTimestamp(r.fields, '发布时间'),
    }
  }))
  .filter(item => {
    if (!item.json.article_id || !item.json.url) return false;
    const pts = item.json.publish_time_ms;
    if (pts === null) return false;
    return pts <= cutoff;
  });

const now = Date.now();
const item = items[0].json;
const article_id = item.article_id || '';
if (!article_id) {
  throw new Error('article_id 为空，拒绝调用极致了，避免 task_key 冲突');
}
const task_key = article_id;
const run_id = `s3-${now}-${Math.random().toString(36).slice(2, 8)}`;
return [{
  json: {
    ...item,
    task_key,
    run_id,
    started_at: now,
    lock_until: now + 10 * 60 * 1000,
  }
}];

const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');
const item = items[0].json;
const since_24h = Date.now() - 86400 * 1000;
