let cached_share_count = 0, cached_collect_count = 0, cached_comment_count = 0;
if (row) {
  let parsed = {};
  try { parsed = JSON.parse(row.result_json || '{}'); } catch(e) {}
  if (parsed.read_count !== undefined || parsed.like_count !== undefined) {
    check_result = 'RECENT_SUCCESS';
    cached_read_count = parsed.read_count || 0;
    cached_like_count = parsed.like_count || 0;
    cached_wow_count = parsed.wow_count || 0;
    cached_share_count = parsed.share_count || 0;
    cached_collect_count = parsed.collect_count || 0;
    cached_comment_count = parsed.comment_count || 0;
  } else {
    check_result = 'SUCCESS_CACHE_INVALID';
  }
}
return [{ json: { ...item, check_result, cached_read_count, cached_like_count, cached_wow_count, cached_share_count, cached_collect_count, cached_comment_count } }];

