const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');
const item = items[0].json;
const { article_id, record_id, run_id, lock_until, started_at, url } = item;
const now = Date.now();
const since_24h = now - 86400 * 1000;
let lock_result = 'CLAIMED';
const txn = db.transaction(() => {
  const sr = db.prepare(`SELECT id FROM metrics_call_log WHERE article_id = ? AND status = 'success' AND started_at >= ? LIMIT 1`).get(article_id, since_24h);
  if (sr) { lock_result = 'RECENT_SUCCESS'; return; }
  const ur = db.prepare(`SELECT id FROM metrics_call_log WHERE article_id = ? AND status = 'uncertain' LIMIT 1`).get(article_id);
  if (ur) { lock_result = 'UNCERTAIN_REVIEW'; return; }
  const pr = db.prepare(`SELECT id, lock_until as lu FROM metrics_call_log WHERE article_id = ? AND status = 'processing' LIMIT 1`).get(article_id);
  if (pr) {
    if (pr.lu > now) { lock_result = 'ALREADY_PROCESSING'; return; }
    db.prepare(`UPDATE metrics_call_log SET status = 'uncertain' WHERE id = ?`).run(pr.id);
    lock_result = 'LOCK_EXPIRED_REVIEW'; return;
  }
  try {
    db.prepare(`INSERT INTO metrics_call_log (article_id, status, provider, run_id, feishu_record_id, url, started_at, lock_until, synced_to_feishu) VALUES (?, 'processing', 'jizhile', ?, ?, ?, ?, ?, 0)`).run(article_id, run_id, record_id, url, started_at, lock_until);
  } catch (e) {
    if (e.code === 'SQLITE_CONSTRAINT_UNIQUE' || String(e.message).includes('UNIQUE')) {
      lock_result = 'ALREADY_PROCESSING';
    } else {
      throw e;
    }
  }
});
txn();
db.close();
return [{ json: { ...item, lock_result } }];

function toNumber(value) {
  if (value === undefined || value === null || value === '') return 0;
  if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
  let s = String(value).trim().replace(/,/g, '');
  if (/万\+?$/.test(s)) return Math.round(Number(s.replace(/万\+?$/, '')) * 10000) || 0;
  if (s.endsWith('+')) s = s.slice(0, -1);
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

const resp = items[0]?.json || {};
let origItem;
try { origItem = $('Compute task_key').first().json; } catch(e) { origItem = resp; }
const now = Date.now();
let jizhile_status, read_count, like_count, wow_count, share_count, collect_count, comment_count, error_code, error_msg;

if (resp.code === 0) {
  const data = resp.data || {};
  jizhile_status = 'success';
  read_count = toNumber(data.read);
  like_count = toNumber(data.zan);
  wow_count = toNumber(data.looking);
  share_count = toNumber(data.share_num);
  collect_count = toNumber(data.collect_num);
  comment_count = toNumber(data.comment_count);
  error_code = null;
  error_msg = null;
} else {
  const errCode = resp.code ?? resp.status ?? 'unknown';
  const errMsg = typeof resp.msg === 'string' ? resp.msg : (typeof resp.message === 'string' ? resp.message : JSON.stringify(resp.message ?? resp.msg ?? ''));
  const fatalCodes = [20002, 20003];
  jizhile_status = fatalCodes.includes(errCode) ? 'failed' : 'uncertain';
  read_count = 0; like_count = 0; wow_count = 0; share_count = 0; collect_count = 0; comment_count = 0;
  error_code = String(errCode).slice(0, 64);
  error_msg = String(errMsg).slice(0, 500);
}

return [{ json: { ...origItem, jizhile_status, read_count, like_count, wow_count, share_count, collect_count, comment_count, error_code, error_msg, finished_at: now } }];

const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');
const item = items[0].json;
const { article_id, run_id, read_count, like_count, wow_count, share_count, collect_count, comment_count, finished_at } = item;
const result_json = JSON.stringify({ read_count, like_count, wow_count, share_count, collect_count, comment_count });
const res = db.prepare(`UPDATE metrics_call_log SET status='success', result_json=?, read_count=?, like_count=?, wow_count=?, share_count=?, collect_count=?, comment_count=?, finished_at=? WHERE article_id=? AND status='processing' AND run_id=?`).run(result_json, read_count, like_count, wow_count, share_count, collect_count, comment_count, finished_at, article_id, run_id);
if (res.changes !== 1) {
  const existing = db.prepare(`SELECT id FROM metrics_call_log WHERE article_id=? AND status='success' AND run_id=? LIMIT 1`).get(article_id, run_id);
  if (!existing) {
    db.close();
    throw new Error(`SQLite success update failed (changes=${res.changes}). article_id=${article_id}, run_id=${run_id}. 人工检查 metrics_call_log。`);
  }
}
db.close();
const sd = $getWorkflowStaticData('global');
if (sd.stage3_run_stats) {
  sd.stage3_run_stats.success_count++;
  sd.stage3_run_stats.claimed_count++;
  sd.stage3_run_stats.total_records++;
}
return [{ json: { ...item, result_json } }];

